fn mutation_path<'a>(mutation:RetainedCloneRef<'a,IdmlMutation>)->RetainedCloneRef<'a,String>{mutation.project(2,|mutation|match mutation{IdmlMutation::ReplacePart{path,..}=>path,_=>unreachable!("part profile")})}
fn part_path<'a>(source:RetainedCloneRef<'a,IdmlSnapshot>,index:usize)->RetainedCloneRef<'a,String>{source.project(0,|doc|&doc.parts).project(index,move|parts|&parts[index]).project(0,|part|&part.path)}
fn part_bytes<'a>(source:RetainedCloneRef<'a,IdmlSnapshot>,index:usize)->RetainedCloneRef<'a,Vec<u8>>{source.project(0,|doc|&doc.parts).project(index,move|parts|&parts[index]).project(1,|part|&part.bytes)}
