fn target_bytes<'a>(package:bool,replaced:Option<usize>,mutation:RetainedCloneRef<'a,IdmlMutation>,base:RetainedCloneRef<'a,IdmlSnapshot>,index:usize)->RetainedCloneRef<'a,Vec<u8>>{if package{part_bytes(document(mutation),index)}else if replaced==Some(index){mutation_bytes(mutation)}else{part_bytes(base,index)}}
fn views<'a>(before:&'a RetainedIdmlAdmission,after:&'a RetainedIdmlAdmission,package:bool,mutation:RetainedCloneRef<'a,IdmlMutation>,base:RetainedCloneRef<'a,IdmlSnapshot>)->Result<(IdmlAdmissionSource<'a>,IdmlAdmissionSource<'a>),ValueError>{Ok((before.admitted_source(base,None)?,if package{after.admitted_source(document(mutation),None)?}else{after.admitted_source(base,Some(mutation_bytes(mutation)))?}))}
